from decimal import Decimal, ROUND_HALF_UP

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

def round_half_up(val):
    return int(Decimal(str(val)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def compute_total(vals, n_items):
    vals_arr = np.array(vals, dtype=float)
    n_missing = np.isnan(vals_arr).sum()
    if n_missing >= 2:
        return np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals_arr)
        raw_val = (ans_sum * n_items) / (n_items - 1)
        tot = round_half_up(raw_val)
        return tot, True
    else:
        tot = int(np.nansum(vals_arr))
        return tot, False

rses_totals, rses_prorateds = [], []
for idx, row in raw.iterrows():
    r_vals = []
    for i in range(1, 11):
        v = row[f'rses_{i}']
        if pd.isna(v) or v < 0 or v > 3:
            r_vals.append(np.nan)
        else:
            if i in [3, 5, 8, 9, 10]:
                r_vals.append(3 - int(v))
            else:
                r_vals.append(int(v))
    tot, pro = compute_total(r_vals, 10)
    rses_totals.append(tot if not pd.isna(tot) else np.nan)
    rses_prorateds.append(pro)

my_rses = pd.DataFrame({'rses_total': rses_totals, 'rses_prorated': rses_prorateds})

for col in my_rses.columns:
    eq = my_rses[col].astype(object).fillna("NaN") == pipe[col].astype(object).fillna("NaN")
