def compute_total_test(vals, n_items, rounding_mode='half_up'):
    vals_arr = np.array(vals, dtype=float)
    n_missing = np.isnan(vals_arr).sum()
    if n_missing >= 2:
        return np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals_arr)
        raw_val = (ans_sum * n_items) / (n_items - 1)
        if rounding_mode == 'half_up':
            from decimal import Decimal, ROUND_HALF_UP
            tot = int(Decimal(str(raw_val)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        elif rounding_mode == 'even':
            tot = round(raw_val)
        elif rounding_mode == 'int':
            tot = int(raw_val)
        return tot, True
    else:
        tot = int(np.nansum(vals_arr))
        return tot, False

rses_totals = []
for idx, row in raw.iterrows():
