    for i in range(1, 11):
        v = row[f'rses_{i}']
        if pd.isna(v) or v < 0 or v > 3:
            r_vals.append(np.nan)
        else:
            if i in [3, 5, 8, 9, 10]:
                r_vals.append(3 - int(v))
            else:
                r_vals.append(int(v))
    tot, pro = compute_total_test(r_vals, 10, rounding_mode='even')
    rses_totals.append(tot if not pd.isna(tot) else np.nan)

print("RSES discrepancies with round half-to-even:", (pd.Series(rses_totals).astype(object).fillna("NaN") != pipe['rses_total'].astype(object).fillna("NaN")).sum())
